/* Fixed fictional logistics records. Rendering and replay are entirely local. */
(function(root){
'use strict';
const freeze=x=>{Object.values(x).forEach(v=>{if(v&&typeof v==='object')freeze(v);});return Object.freeze(x);};
const shipments=freeze([
 {id:'CL-2401',name:'鲜奶配送 · 北区门店',cargo:'冷藏乳品',range:[2,8],points:[ [0,55,178,4.2,68,'仓库出发'],[15,140,178,4.5,69,'城市干道'],[30,245,125,5.1,70,'转运站'],[45,355,125,8.7,73,'开门卸货'],[60,460,178,6.2,70,'恢复制冷'],[75,575,178,4.8,68,'配送完成'] ]},
 {id:'CL-2402',name:'冷冻食材 · 东区配送',cargo:'冷冻食品',range:[-22,-18],points:[ [0,55,178,-20.4,62,'仓库出发'],[15,155,178,-20.1,62,'城市干道'],[30,265,225,-19.8,64,'环线入口'],[45,365,225,-19.2,65,'园区检查'],[60,470,178,-18.9,64,'门店抵达'],[75,575,178,-19.6,62,'配送完成'] ]},
 {id:'CL-2403',name:'鲜果配送 · 南区商超',cargo:'鲜果',range:[3,10],points:[ [0,55,178,6.4,75,'仓库出发'],[15,150,178,6.7,76,'城市干道'],[30,250,95,7.1,76,'环线入口'],[45,360,95,7.8,78,'中途停靠'],[60,470,178,8.3,78,'商超抵达'],[75,575,178,7.6,75,'配送完成'] ]}
]);
const zones=['入口展示','生鲜区','冷藏区','日用品区','促销区','结算区'];
const categories=['生鲜食品','冷藏乳品','生活用品'];
const eventTypes=['浏览','搜索','加购','购买'];
// Fixed, reproducible synthetic events: no identities, devices, or customer tracking.
const events=freeze(Array.from({length:144},(_,i)=>({id:'EV-'+String(i+1).padStart(3,'0'),minute:540+(i%12)*15,zone:(i*7+Math.floor(i/12))%6,category:categories[(i+Math.floor(i/6))%3],type:eventTypes[(i+Math.floor(i/4))%4],count:1+(i*3)%5+[0,3,2,1,4,2][(i*7+Math.floor(i/12))%6]})));
const aircraft=freeze([
 {id:'UAV-01',name:'轻载配送一号',task:'园区仓 → 北门驿站',load:1.8,maxLoad:3,points:[[0,60,170,100,0,'待起飞','正常'],[2,140,90,94,30,'爬升','正常'],[4,270,70,87,55,'巡航','正常'],[6,410,90,79,55,'巡航','边界提醒'],[8,510,145,72,25,'进近','正常'],[10,575,170,68,0,'已降落','正常']]},
 {id:'UAV-02',name:'冷链配送二号',task:'中心仓 → 东区收货点',load:2.4,maxLoad:3,points:[[0,60,170,88,0,'待起飞','正常'],[2,150,240,81,25,'爬升','正常'],[4,285,250,73,45,'巡航','正常'],[6,425,245,65,45,'悬停检查','边界提醒'],[8,510,210,57,20,'进近','正常'],[10,575,170,52,0,'已降落','正常']]},
 {id:'UAV-03',name:'返航演练三号',task:'园区仓 → 中转平台 → 园区仓',load:0.9,maxLoad:2,points:[[0,60,170,46,0,'待起飞','正常'],[2,175,105,39,25,'爬升','正常'],[4,330,105,30,40,'巡航','正常'],[6,250,140,24,35,'低电返航','正常'],[8,145,165,19,15,'进近','正常'],[10,60,170,16,0,'已降落','正常']]}
]);
const missions=freeze(aircraft.map((a,i)=>({id:'TASK-0'+(i+1),name:a.task,aircraft:a.id,load:a.load})));
const safetyEvents=freeze([{aircraft:'UAV-01',step:3,title:'接近围栏边界',detail:'预设路线已回到围栏内，记录保留供复盘。',severity:'提醒'},{aircraft:'UAV-02',step:3,title:'边界附近悬停检查',detail:'本地轨迹暂停检查后继续进近。',severity:'提醒'},{aircraft:'UAV-03',step:3,title:'低电量返航',detail:'预设电量降至 24%，回放切换返航阶段。',severity:'警告'},{aircraft:'UAV-03',step:4,title:'低电量进近',detail:'预设电量 19%，回放继续降落。',severity:'警告'}]);
function coldRows(id,window){const s=shipments.find(x=>x.id===id)||shipments[0];return s.points.filter(p=>window==='all'||(window==='early'?p[0]<=30:p[0]>=45));}
function filteredEvents(filters){return events.filter(e=>(!filters.event||filters.event==='all'||e.type===filters.event)&&(!filters.category||filters.category==='all'||e.category===filters.category)&&(!filters.time||filters.time==='all'||(filters.time==='morning'?e.minute<630:e.minute>=630)));}
function hotCounts(filters){const rows=filteredEvents(filters);return zones.map((zone,i)=>({zone,index:i,count:rows.filter(e=>e.zone===i).reduce((n,e)=>n+e.count,0)}));}
let host=null,page='',state=null,timer=null,playing=false,storageFailed=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=p=>p==='coldchain'?{shipment:'CL-2401',window:'all',step:0,tab:'trajectory'}:p==='analytics'?{event:'all',category:'all',time:'all',tab:'heatmap',zone:'all'}:{aircraft:'UAV-01',task:'TASK-01',assignment:'TASK-01',step:0,tab:'flight'};
function key(){return root.PresetDemo.storageKey('logistics_'+page);}
function restore(){state=defaults(page);try{const saved=JSON.parse(root.localStorage.getItem(key())||'null');if(saved&&typeof saved==='object'){for(const k of Object.keys(state))if(typeof saved[k]===typeof state[k])state[k]=saved[k];}}catch{storageFailed=true;}
 if(page==='coldchain'){if(!shipments.some(s=>s.id===state.shipment))state.shipment=shipments[0].id;if(!['all','early','late'].includes(state.window))state.window='all';if(!['trajectory','temperature'].includes(state.tab))state.tab='trajectory';}
 if(page==='analytics'){if(!['all',...eventTypes].includes(state.event))state.event='all';if(!['all',...categories].includes(state.category))state.category='all';if(!['all','morning','afternoon'].includes(state.time))state.time='all';if(!['heatmap','events'].includes(state.tab))state.tab='heatmap';if(!['all',...zones.map((_,i)=>String(i))].includes(state.zone))state.zone='all';}
 if(page==='drone'){if(!missions.some(m=>m.id===state.task))state.task='TASK-01';if(!missions.some(m=>m.id===state.assignment))state.assignment='TASK-01';if(!aircraft.some(a=>a.id===state.aircraft))state.aircraft=aircraft[0].id;if(!['flight','safety'].includes(state.tab))state.tab='flight';state.assignment=missions.find(m=>m.aircraft===state.aircraft).id;}
 if(page!=='analytics')state.step=Math.max(0,Math.min(points().length-1,Number.isFinite(state.step)?Math.floor(state.step):0));
}
function save(){try{root.localStorage.setItem(key(),JSON.stringify(state));}catch{storageFailed=true;}}
function points(){return page==='coldchain'?coldRows(state.shipment,state.window):(aircraft.find(a=>a.id===state.aircraft)||aircraft[0]).points;}
function pause(){if(timer!==null)root.clearInterval(timer);timer=null;playing=false;}
function stop(){pause();if(host){host.onclick=null;host.onchange=null;}host=null;}
function step(){state.step=Math.min(points().length-1,state.step+1);if(state.step===points().length-1)pause();save();draw();}
function replay(){return `<div class="pl-replay toolbar"><button class="btn" data-action="back" ${state.step===0?'disabled':''}>上一步</button><button class="btn primary" data-action="play">${playing?'暂停':'播放'}</button><button class="btn" data-action="next" ${state.step===points().length-1?'disabled':''}>下一步</button><button class="btn" data-action="reset">重置回放</button><span class="muted">节点 ${state.step+1} / ${points().length} · ${points()[state.step][0]} min</span></div><div class="pl-timeline">${points().map((p,i)=>`<button class="${i===state.step?'active':''}" data-step="${i}" aria-pressed="${i===state.step}"><b>${p[0]} min</b><small>${esc(p[5])}</small></button>`).join('')}</div>`;}
function select(label,name,choices,value){return `<label class="pl-filter">${label}<select data-filter="${name}">${choices.map(c=>`<option value="${esc(c[0])}" ${c[0]===value?'selected':''}>${esc(c[1])}</option>`).join('')}</select></label>`;}
function tabs(items){return `<div class="pl-tabs" role="group" aria-label="视图切换">${items.map(([id,title])=>`<button class="btn ${state.tab===id?'primary':''}" data-tab="${id}" aria-pressed="${state.tab===id}">${title}</button>`).join('')}</div>`;}
function table(heads,rows){return `<div class="table-scroll"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;}
function metrics(items){return `<div class="metric-strip">${items.map(([a,b,c])=>`<div><span>${a}</span><strong>${b}<small>${c||''}</small></strong></div>`).join('')}</div>`;}
function routeSvg(rows,index,drone){const p=rows[index],line=rows.map(p=>p[1]+','+p[2]).join(' ');return `<svg class="pl-map" viewBox="0 0 640 310" role="img" aria-label="${drone?'无人机预设飞行轨迹':'冷链历史位置轨迹'}，当前位置 ${p[1]}, ${p[2]}"><rect width="640" height="310" fill="#f1f6fb"/><path d="M0 85H640M0 175H640M0 245H640M140 0V310M320 0V310M510 0V310" stroke="#fff" stroke-width="24"/>${drone?'<rect x="35" y="45" width="565" height="230" rx="20" stroke="#169b84" fill="#0e94880a" stroke-dasharray="7 5"/><text x="47" y="35" fill="#167b6c">教学电子围栏 / 非真实空域</text>':'<rect x="27" y="205" width="88" height="54" rx="8" fill="#dbe7f4"/><text x="40" y="236">配送仓</text><rect x="525" y="205" width="90" height="54" rx="8" fill="#dbeee8"/><text x="535" y="236">配送终点</text>'}<polyline points="${line}" fill="none" stroke="#bccbdf" stroke-width="7" stroke-linejoin="round"/><polyline points="${rows.slice(0,index+1).map(p=>p[1]+','+p[2]).join(' ')}" fill="none" stroke="#2563eb" stroke-width="5"/>${rows.map((q,i)=>`<circle cx="${q[1]}" cy="${q[2]}" r="5" fill="${i<=index?'#2563eb':'#94a3b8'}"/>`).join('')}<circle cx="${p[1]}" cy="${p[2]}" r="12" fill="#0f766e" stroke="white" stroke-width="4"/><text x="20" y="295" fill="#64748b" font-size="12">示意坐标 x/y · 固定样例位置 · 不代表真实地图或 GPS</text></svg>`;}
function temperatureChart(s,rows){const temps=rows.map(p=>p[3]),lo=Math.min(s.range[0],...temps)-1,hi=Math.max(s.range[1],...temps)+1,y=t=>180-(t-lo)/(hi-lo)*145,x=i=>55+i*500/Math.max(1,rows.length-1);return `<svg class="pl-chart" viewBox="0 0 640 225" role="img" aria-label="所选时段温度曲线，合格范围 ${s.range.join(' 到 ')} 摄氏度"><rect x="45" y="${y(s.range[1])}" width="525" height="${y(s.range[0])-y(s.range[1])}" fill="#dcfce7"/><path d="M45 20V185H585" stroke="#94a3b8" fill="none"/><text x="48" y="15" font-size="12">温度 °C / 绿色区域为 ${s.range.join(' ~ ')} °C</text><polyline points="${rows.map((p,i)=>x(i)+','+y(p[3])).join(' ')}" stroke="#2563eb" stroke-width="3" fill="none"/>${rows.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p[3])}" r="${i===state.step?7:4}" fill="${p[3]<s.range[0]||p[3]>s.range[1]?'#dc2626':'#2563eb'}"/><text x="${x(i)-12}" y="${y(p[3])-12}" font-size="12">${p[3]}</text><text x="${x(i)-12}" y="205" font-size="12">${p[0]}m</text>`).join('')}</svg>`;}
function cold(){const s=shipments.find(x=>x.id===state.shipment),rows=points(),p=rows[state.step],bad=rows.filter(p=>p[3]<s.range[0]||p[3]>s.range[1]).length;
 return `<div class="pl-filters">${select('配送运单','shipment',shipments.map(x=>[x.id,x.id+' · '+x.name]),state.shipment)}${select('历史时段','window',[['all','全程 0–75 min'],['early','前半程 0–30 min'],['late','后半程 45–75 min']],state.window)}</div>${metrics([['当前温度',p[3],'°C'],['温度要求',s.range.join(' ~ '),'°C'],['当前湿度',p[4],'%'],['所选时段超温',bad,'次']])}${tabs([['trajectory','历史轨迹'],['temperature','温度明细']])}<div class="pl-columns"><section class="card"><div class="section-title"><h2>${state.tab==='trajectory'?'配送历史轨迹':'温度变化曲线'}</h2><span class="badge blue">${p[0]} min · ${p[5]}</span></div>${state.tab==='trajectory'?routeSvg(rows,state.step,false):temperatureChart(s,rows)}${replay()}</section><section class="card"><h2>运单摘要</h2><dl class="pl-details"><dt>运单</dt><dd>${s.id}</dd><dt>货物</dt><dd>${s.cargo}</dd><dt>当前位置</dt><dd>x ${p[1]} / y ${p[2]}</dd><dt>样本范围</dt><dd>${rows[0][0]}–${rows.at(-1)[0]} min</dd><dt>温控状态</dt><dd>${p[3]<s.range[0]||p[3]>s.range[1]?'超出预设阈值':'符合预设阈值'}</dd></dl><p class="muted">轨迹和温度来自同一组固定采样点。切换运单或时段会重置回放位置。</p><button class="btn" data-action="original">进入冷链监控操作 ↓</button></section></div><section class="card pl-bottom"><h2>历史采样记录</h2>${table(['分钟','位置 x / y','温度','湿度','节点','温控'],rows.map((r,i)=>`<tr ${i===state.step?'class="pl-current"':''}><td><button class="text-btn" data-step="${i}">${r[0]} min</button></td><td>${r[1]} / ${r[2]}</td><td>${r[3]} °C</td><td>${r[4]}%</td><td>${r[5]}</td><td>${r[3]<s.range[0]||r[3]>s.range[1]?'<span class="badge red">超温</span>':'正常'}</td></tr>`).join(''))}</section>`;
}
function analytics(){const rows=filteredEvents(state),counts=hotCounts(state),total=counts.reduce((n,x)=>n+x.count,0),max=Math.max(1,...counts.map(x=>x.count)),purchases=rows.filter(e=>e.type==='购买').reduce((n,e)=>n+e.count,0),detail=state.zone==='all'?rows:rows.filter(e=>e.zone===Number(state.zone));return `<div class="pl-filters">${select('行为类型','event',[['all','全部行为'],...eventTypes.map(x=>[x,x])],state.event)}${select('商品品类','category',[['all','全部品类'],...categories.map(x=>[x,x])],state.category)}${select('时间范围','time',[['all','09:00–11:45'],['morning','09:00–10:15'],['afternoon','10:30–11:45']],state.time)}</div>${metrics([['行为总次数',total,'次'],['匹配记录',rows.length,'条'],['购买次数',purchases,'次'],['最热区域',counts.reduce((a,b)=>b.count>a.count?b:a).zone,'']])}${tabs([['heatmap','消费热点分布'],['events','行为记录']])}<div class="pl-columns"><section class="card"><div class="section-title"><h2>${state.tab==='heatmap'?'门店消费热点':'固定行为事件'}</h2><span class="badge blue">筛选实时计算</span></div>${state.tab==='heatmap'?`<div class="pl-store-label">门店平面示意 · 点击区域查看计数</div><div class="pl-heatmap">${counts.map(c=>`<button data-zone="${c.index}" class="pl-heat-cell ${state.zone===String(c.index)?'selected':''}" style="--heat:${0.10+0.45*c.count/max}" aria-pressed="${state.zone===String(c.index)}"><span>${c.zone}</span><strong>${c.count}</strong><small>${total?(100*c.count/total).toFixed(1):'0.0'}% 的筛选事件次数</small></button>`).join('')}</div><div class="pl-legend"><span>较低</span><i></i><span>较高 · 按当前筛选最大值归一化</span></div>`:table(['记录','时间','区域','品类','行为','次数'],detail.slice(0,24).map(e=>`<tr><td>${e.id}</td><td>${Math.floor(e.minute/60)}:${String(e.minute%60).padStart(2,'0')}</td><td>${zones[e.zone]}</td><td>${e.category}</td><td>${e.type}</td><td>${e.count}</td></tr>`).join('')||'<tr><td colspan="6">当前条件暂无样例记录</td></tr>')}${state.tab==='events'?`<p class="muted">当前区域匹配 ${detail.length} 条，显示前 ${Math.min(24,detail.length)} 条；统计使用全部匹配记录。</p>`:''}</section><section class="card"><h2>${state.zone==='all'?'区域排行':zones[Number(state.zone)]+' · 行为明细'}</h2>${state.zone==='all'?counts.slice().sort((a,b)=>b.count-a.count||a.index-b.index).map((c,i)=>`<button class="pl-ranking" data-zone="${c.index}"><span>${i+1}. ${c.zone}</span><b>${c.count} 次</b></button>`).join(''):eventTypes.map(t=>`<div class="pl-ranking"><span>${t}</span><b>${detail.filter(e=>e.type===t).reduce((n,e)=>n+e.count,0)} 次</b></div>`).join('')}<button class="btn pl-bottom" data-action="clearZone">全部区域</button><p class="muted">144 条预设聚合事件，无客户身份、定位或真实消费者记录。热度表示次数，不代表独立人数。</p><h3>消费习惯摘要</h3><p class="muted">品类次数：${categories.map(c=>c+' '+rows.filter(e=>e.category===c).reduce((n,e)=>n+e.count,0)).join(' · ')}<br>09:00–10:15：${rows.filter(e=>e.minute<630).reduce((n,e)=>n+e.count,0)} 次；10:30–11:45：${rows.filter(e=>e.minute>=630).reduce((n,e)=>n+e.count,0)} 次<br>当前筛选搜索行为：${rows.filter(e=>e.type==='搜索').reduce((n,e)=>n+e.count,0)} 次</p><button class="btn" data-action="resetFilters">重置筛选</button></section></div>`;}
function drone(){const a=aircraft.find(a=>a.id===state.aircraft),rows=points(),p=rows[state.step],visible=safetyEvents.filter(e=>e.aircraft===a.id&&e.step<=state.step);return `<section class="card pl-bottom"><div class="section-title"><h2>配送任务分配</h2><span class="badge blue">本地方案管理</span></div><div class="pl-filters">${select('待载入任务方案','task',missions.map(m=>[m.id,m.id+' · '+m.name+' · '+m.aircraft]),state.task)}<button class="btn primary" data-action="loadMission">载入任务方案</button></div><p class="muted">当前已分配：${state.assignment} → ${a.id} · ${a.task} · ${p[5]}${state.task!==state.assignment?'；所选新方案尚未载入':''}。载入仅切换固定本地回放，不发送调度指令。</p></section><div class="pl-aircraft">${aircraft.map(x=>`<button data-aircraft="${x.id}" class="card ${x.id===a.id?'selected':''}" aria-pressed="${x.id===a.id}"><span class="badge ${x.id===a.id?'blue':'gray'}">${x.id}</span><h3>${x.name}</h3><p>${x.task}</p><small>载荷 ${x.load} / ${x.maxLoad} kg · 固定配送任务</small></button>`).join('')}</div>${metrics([['回放电量',p[3],'%'],['回放高度',p[4],'m'],['载荷',a.load+' / '+a.maxLoad,'kg'],['回放时间',p[0],'min']])}${tabs([['flight','飞行路径'],['safety','安全事件']])}<div class="pl-columns"><section class="card"><div class="section-title"><h2>${state.tab==='flight'?'配送路径回放':'安全事件回放'}</h2><span class="badge ${p[3]<25?'red':'blue'}">${p[5]}</span></div>${state.tab==='flight'?routeSvg(rows,state.step,true):table(['时间','事件','级别','处置记录'],visible.map(e=>`<tr><td>${rows[e.step][0]} min</td><td>${e.title}</td><td><span class="badge ${e.severity==='警告'?'red':'blue'}">${e.severity}</span></td><td>${e.detail}</td></tr>`).join('')||'<tr><td colspan="4">截至当前节点未触发安全事件，可播放后续预设记录。</td></tr>')}${replay()}</section><section class="card"><h2>任务与安全状态</h2><dl class="pl-details"><dt>已分配方案</dt><dd>${state.assignment}</dd><dt>任务</dt><dd>${a.task}</dd><dt>飞行阶段</dt><dd>${p[5]}</dd><dt>围栏状态</dt><dd>${p[6]}</dd><dt>电池策略</dt><dd>${p[3]<25?'低电量 / 返航降落':'预设安全电量'}</dd><dt>载荷检查</dt><dd>${a.load<=a.maxLoad?'额定载荷内':'超载'}</dd><dt>已发生事件</dt><dd>${visible.length} 条</dd></dl><p class="muted">全部高度、电量、载荷和围栏状态均为固定本地仿真。按钮只控制记录回放，不连接或操控无人机。</p><h3>本任务预设安全事件</h3>${safetyEvents.filter(e=>e.aircraft===a.id).map(e=>`<div class="pl-event"><b>${rows[e.step][0]} min · ${e.title}</b><small>${e.step<=state.step?'已回放':'待回放'} · ${e.detail}</small></div>`).join('')}</section></div>`;}
const css=`.pl-panel{--pl-blue:#2563eb}.pl-panel .pl-columns{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(260px,1fr);gap:20px}.pl-panel .card{min-width:0}.pl-panel .pl-filters{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0}.pl-panel .pl-filter{display:grid;gap:7px;font-size:13px;color:#475569;min-width:170px}.pl-panel select{padding:10px 12px;border:1px solid #ced8e5;border-radius:8px;background:#fff;color:#1e293b;max-width:100%}.pl-panel .pl-tabs{display:flex;gap:8px;margin:18px 0}.pl-panel .pl-map,.pl-panel .pl-chart{width:100%;display:block;border-radius:12px;margin:12px 0}.pl-panel .pl-timeline{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:6px;margin-top:18px}.pl-panel .pl-timeline button{padding:10px 3px;border:1px solid #d8e2ee;border-radius:8px;background:#f8fafc;color:#475569;cursor:pointer}.pl-panel .pl-timeline .active{background:#eaf1ff;border-color:#2563eb;color:#1d4ed8}.pl-panel small{display:block;font-size:12px;line-height:1.7}.pl-panel .pl-replay{flex-wrap:wrap}.pl-panel .pl-details{display:grid;grid-template-columns:90px 1fr;gap:15px 10px;font-size:14px}.pl-panel dt{color:#64748b}.pl-panel dd{margin:0;font-weight:600}.pl-panel .pl-bottom{margin-top:20px}.pl-panel .pl-current{background:#edf5ff}.pl-panel .pl-heatmap{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:18px;background:#f1f5f9;border:2px solid #cbd5e1;border-radius:12px}.pl-panel .pl-heat-cell{border:2px solid transparent;background:rgba(37,99,235,var(--heat));border-radius:8px;min-height:150px;text-align:left;padding:16px;color:#102c52;cursor:pointer}.pl-panel .pl-heat-cell strong{font-size:32px;display:block;margin:10px 0}.pl-panel .selected{outline:3px solid #2563eb;outline-offset:2px}.pl-panel .pl-store-label{font-size:12px;color:#64748b;margin:12px 0}.pl-panel .pl-legend{display:flex;align-items:center;gap:10px;font-size:12px;margin-top:18px;color:#64748b}.pl-panel .pl-legend i{display:block;width:90px;height:10px;background:linear-gradient(90deg,#e8efff,#427ced);border-radius:5px}.pl-panel .pl-ranking{display:flex;justify-content:space-between;gap:10px;width:100%;padding:15px 4px;border:0;border-bottom:1px solid #e2e8f0;background:white;text-align:left;color:#334155;font-size:14px}.pl-panel button.pl-ranking{cursor:pointer}.pl-panel .pl-aircraft{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:22px 0}.pl-panel .pl-aircraft button{text-align:left;cursor:pointer;color:#1e293b}.pl-panel .pl-aircraft p{font-size:13px;color:#64748b}.pl-panel .pl-event{border-left:3px solid #f59e0b;padding:10px 12px;margin:12px 0;background:#fffbeb;font-size:13px}.pl-panel button:focus-visible,.pl-panel a:focus-visible,.pl-panel select:focus-visible{outline:3px solid #f59e0b;outline-offset:3px}.pl-panel button:disabled{opacity:.45;cursor:default}.pl-panel .pl-warning{color:#b45309;font-size:13px}@media(max-width:1000px){.pl-panel .pl-columns{grid-template-columns:1fr}.pl-panel .pl-aircraft{gap:10px}}@media(max-width:640px){.pl-panel .pl-aircraft{grid-template-columns:1fr}.pl-panel .pl-heatmap{grid-template-columns:repeat(2,minmax(0,1fr));padding:10px}.pl-panel .pl-heat-cell{padding:12px;min-height:125px}.pl-panel .pl-timeline{grid-template-columns:repeat(3,minmax(0,1fr))}.pl-panel .pl-filter{width:100%;min-width:0}.pl-panel .pl-details{grid-template-columns:80px 1fr}}`;
function draw(){if(!host)return;const titles={coldchain:['冷链历史追踪','COLD CHAIN / HISTORY'],analytics:['消费行为分析','RETAIL / BEHAVIOR'],drone:['无人机配送调度','DRONE / OPERATIONS']};host.innerHTML=`<section class="pl-panel"><style>${css}</style><div class="page-head"><div><div class="eyebrow">${titles[page][1]}</div><h1>${titles[page][0]}</h1><p class="muted">固定虚构教学数据 · ${page==='analytics'?'本地筛选与统计':'本地记录回放'} · 不连接真实设备、客户数据或模型服务</p></div><span class="badge blue">预设样例</span></div>${storageFailed?'<p class="pl-warning">浏览器存储暂不可用，本次操作仍可继续，但可能无法保留。</p>':''}${page==='coldchain'?cold():page==='analytics'?analytics():drone()}</section>`;}
function action(event){const b=event.target.closest('button');if(!b||b.disabled||!host?.contains(b))return;const d=b.dataset;if(d.action==='original'){root.document?.getElementById('preset-coldchain-original')?.scrollIntoView({behavior:'smooth',block:'start'});return;}if(d.tab!==undefined){state.tab=d.tab;}else if(d.step!==undefined){pause();state.step=Number(d.step);}else if(d.zone!==undefined){state.zone=d.zone;}else if(d.aircraft!==undefined){pause();state.aircraft=d.aircraft;state.task=state.assignment=missions.find(m=>m.aircraft===d.aircraft).id;state.step=0;}else if(d.action==='loadMission'){pause();state.assignment=state.task;state.aircraft=missions.find(m=>m.id===state.task).aircraft;state.step=0;state.tab='flight';}else if(d.action==='play'){if(playing)pause();else{if(state.step===points().length-1)state.step=0;playing=true;timer=root.setInterval(step,1100);}}else if(d.action==='next'){pause();step();return;}else if(d.action==='back'){pause();state.step=Math.max(0,state.step-1);}else if(d.action==='reset'){pause();state.step=0;}else if(d.action==='clearZone'){state.zone='all';}else if(d.action==='resetFilters'){state=defaults(page);}else{return;}save();draw();}
function change(event){const name=event.target.dataset?.filter;if(!name||!Object.hasOwn(state,name))return;pause();state[name]=event.target.value;if(page!=='analytics'&&name!=='task')state.step=0;save();draw();}
function render(container,p){if(!['coldchain','analytics','drone'].includes(p))return false;stop();host=container;page=p;storageFailed=false;restore();draw();host.onclick=action;host.onchange=change;return true;}
root.PresetLogisticsPanels={render,stop,data:{shipments,events,zones,aircraft,missions,safetyEvents},calculate:{coldRows,filteredEvents,hotCounts}};
})(typeof window==='undefined'?globalThis:window);
